def seed_history(apps, schema_editor):
    """Give every existing home fence an 'initial' history row mirroring its
    current state, so the audit trail starts complete. Nothing is changed on
    the fences themselves."""
    GeoFence = apps.get_model('api', 'GeoFence')
    Change = apps.get_model('api', 'HomeLocationChange')
    for f in GeoFence.objects.exclude(owner_email=''):
        if Change.objects.filter(fence=f).exists():
            continue
        status = f.status if f.status in ('Pending', 'Approved', 'Rejected') else 'Pending'
        Change.objects.create(
            email=f.owner_email.strip().lower(), kind='initial', status=status, name=f.name or '',
            latitude=f.latitude, longitude=f.longitude, radius_meters=f.radius_meters,
            captured_accuracy=f.captured_accuracy, fence=f, requested_by=f.created_by or f.owner_email,
            reviewer=f.reviewer or '', reviewed_at=f.reviewed_at,
            review_note='Recorded from the existing home location when change requests were introduced.',
        )


